  const fields = foundryElement.fields || {};
  return {
    ...fields,
    id: foundryElement.id || fields.id || `dbm_${Date.now()}`,
    name: foundryElement.title || fields.name || 'Untitled Item',
    description: foundryElement.content || fields.description || '',
